   563:std::string CCodeGen::makeParamCType(ParameterDecl* p, bool isDeclare) {
   564:    // P14.1.5: ParamArray → SAFEARRAY* (always Variant array)
   565:    if (p->isParamArray) {
   566:        return "SAFEARRAY* " + cIdent(p->name);
   567:    }
   568:
   569:    std::string cType = mapTypeRef(p->asType.get());
   570:    std::string cName = cIdent(p->name);
   571:
   572:    // Fix 081e: Declare函数中ByVal Long/LongPtr参数映射为intptr_t
   573:    // VB6 Long在Declare中常用于传句柄/指针 (ByVal hdc As Long等),
   574:    // VB6是32位环境,Long=4字节=指针大小; 但x64下指针8字节,int32_t不够。
   575:    // 将Declare中ByVal Long和ByVal LongPtr都映射为intptr_t:
   576:    //   x86: intptr_t=4字节, 与VB6 Long兼容
   577:    //   x64: intptr_t=8字节, 可容纳指针/句柄值
   578:    // 纯值参数(如CodePage)传入intptr_t也不影响正确性(低32位包含值)。
   579:    // ByRef Long参数不受影响(已映射为int32_t*,指针大小由架构决定)。
   580:    if (isDeclare && p->isByVal && cType == "int32_t") {
   581:        // 只对SimpleTypeRef中的Long/LongPtr提升为intptr_t
   582:        if (p->asType && p->asType->kind == ASTNodeKind::SimpleTypeRef) {
   583:            auto& simpleP = static_cast<SimpleTypeRef&>(*p->asType);
   584:            if (simpleP.name == "Long" || simpleP.name == "LongPtr") {
   585:                cType = "intptr_t";
   586:            }
   587:        }
   588:    }
   589:
   590:    // Fix 010: As Any 参数 — VB6中Any仅用于Declare, ByRef/ByVal均映射为void*
   591:    // 不额外添加ByRef指针 (void*已是"指向任意类型的指针")
   592:    bool isAnyType = false;
   593:    if (p->asType && p->asType->kind == ASTNodeKind::SimpleTypeRef) {
   594:        auto& simpleType = static_cast<SimpleTypeRef&>(*p->asType);
   595:        if (simpleType.name == "Any" || simpleType.name == "any") {
   596:            isAnyType = true;
   597:            cType = "void*";
   598:        }
   599:    }
   600:
   601:    // Fix 010r-6 rev2: ByRef array parameters need vb6_SafeArray1D** (double pointer)
   602:    // so the callee can assign a new SafeArray (e.g. ReDim) and the caller sees it.
