   575:    // 将Declare中ByVal Long和ByVal LongPtr都映射为intptr_t:
   576:    //   x86: intptr_t=4字节, 与VB6 Long兼容
   577:    //   x64: intptr_t=8字节, 可容纳指针/句柄值
